/** The five access promises (P1-P5). Words live in ACCESS-PROMISES.md and `access.promise.*`. */
export type PromiseId = 'P1' | 'P2' | 'P3' | 'P4' | 'P5';

export interface AccessPromise {
  id: PromiseId;
  /** i18n key of Kay's sentence: `access.promise.${id}`. */
  titleKey: string;
  /** Rules that cite this promise. CAP- and HP- ids are generated by G and are not checked in D's test. */
  ruleIds: string[];
}

export const PROMISES: AccessPromise[] = [
  { id: 'P1', titleKey: 'access.promise.P1', ruleIds: ['IN-3', 'IN-7', 'IN-10', 'CAP-1'] },
  { id: 'P2', titleKey: 'access.promise.P2', ruleIds: ['IN-11'] },
  { id: 'P3', titleKey: 'access.promise.P3', ruleIds: ['A11Y-1', 'A11Y-2', 'IN-4', 'IN-5'] },
  { id: 'P4', titleKey: 'access.promise.P4', ruleIds: ['IN-1', 'IN-2', 'IN-6', 'IN-8'] },
  { id: 'P5', titleKey: 'access.promise.P5', ruleIds: ['IN-12'] },
];
